  [4 + look, 1, 'eye'],
  [5 + look, 1, 'eye'],
  [12 + look, 1, 'eye'],
  [13 + look, 1, 'eye'],
]

// 口は胴の上の段の真ん中に2画素。胴の下の段は輪郭なので、口も目も置かない。
